# Example 7: package repeated logic into reusable functions
def classify_score(score):
    if score >= 90:
        return "High"
    elif score >= 75:
        return "Moderate"
    return "Needs support"

def to_int_safe(text):
    try:
        return int(text)
    except ValueError:
        return None

